"""Lecture 27 vignette pool B -- Arterial Occlusive Disease and Aortic Aneurysm:
acute limb ischemia (arterial thrombosis/embolism), atheroembolism and carotid
artery disease.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.

Patient vignettes with a varied lead-in. Acute limb ischemia categories are
described in words, never by their Rutherford labels, and the marginally
threatened category is never keyed on its arterial Doppler (slide 62 and the
slide 65 table disagree). Carotid stenosis percentages in stems sit away from
50, 70 and 80. Scope caps live in cms_e5l27_scope.py.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5l27_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d

def M(d, mis):
    """Attach the misconception each distractor stands for (WRITER.md rule 5), keyed by option text."""
    d["mis"] = mis
    return d


